### Hono.js RPC Client with Type Safety

Source: https://context7.com/honojs/website/llms.txt

Implements a type-safe RPC client using `hono/client` to interact with the Hono.js server. Demonstrates making GET and POST requests, handling different response statuses, and configuring custom headers or credentials. Includes examples of type inference helpers and URL generation.

```typescript
// ========== client.ts ==========
import { hc } from 'hono/client'
import type { InferRequestType, InferResponseType } from 'hono/client'
import type { AppType } from './server'

// Create typed client
const client = hc<AppType>('http://localhost:8787/')

// GET request
async function getHello() {
  const res = await client.api.hello.$get()
  if (res.ok) {
    const data = await res.json() // { message: string }
    console.log(data.message)
  }
}

// POST request with form data
async function createPost() {
  const res = await client.api.posts.$post({
    form: {
      title: 'Hello',
      body: 'Hono is a cool project',
    },
  })

  if (res.status === 201) {
    const data = await res.json() // { ok: boolean, message: string, post: {...} }
    console.log(data.post.id)
  }
}

// GET with path parameters and query
async function getPost() {
  const res = await client.api.posts[':id'].$get({
    param: { id: '123' },
    query: { includeComments: 'true' },
  })

  // Handle different status codes
  if (res.status === 404) {
    const data = await res.json() // { error: string }
    console.log(data.error)
  }

  if (res.status === 200) {
    const data = await res.json() // { post: {...}, comments?: [] }
    console.log(data.post)
  }
}

// Custom headers
async function withHeaders() {
  const res = await client.api.posts.$post(
    {
      form: { title: 'Test', body: 'Content' }
    },
    {
      headers: {
        'X-Custom-Header': 'value',
      },
    }
  )
}

// Client with common headers and credentials
const authenticatedClient = hc<AppType>('http://localhost:8787/', {
  headers: {
    Authorization: 'Bearer TOKEN',
  },
  init: {
    credentials: 'include', // Send cookies
  },
})

// Type inference helpers
type PostRequestType = InferRequestType<typeof client.api.posts.$post>
type PostResponseType = InferResponseType<typeof client.api.posts.$post>
type Post404Type = InferResponseType<typeof client.api.posts[':id'].$get, 404>

// Get URL object
const url = client.api.posts[':id'].$url({ param: { id: '123' } })
console.log(url.pathname) // /api/posts/123

```

