### Hono.js RPC Server with Zod Validation

Source: https://context7.com/honojs/website/llms.txt

Defines an RPC server using Hono.js, setting up routes with Zod validators for request data. It exports the server's type definition (`AppType`) for client-side consumption. Handles GET, POST, and parameterized GET requests, including error handling for not found resources.

```typescript
// ========== server.ts ==========
import { Hono } from 'hono'
import { zValidator } from '@hono/zod-validator'
import { z } from 'zod'

const app = new Hono()

const postSchema = z.object({
  title: z.string(),
  body: z.string(),
})

const route = app
  .get('/api/hello', (c) => {
    return c.json({ message: 'Hello from server!' })
  })
  .post(
    '/api/posts',
    zValidator('form', postSchema),
    (c) => {
      const { title, body } = c.req.valid('form')
      return c.json({
        ok: true,
        message: 'Created!',
        post: { id: '123', title, body }
      }, 201)
    }
  )
  .get(
    '/api/posts/:id',
    zValidator('query', z.object({ includeComments: z.coerce.boolean().optional() })),
    async (c) => {
      const { id } = c.req.param()
      const { includeComments } = c.req.valid('query')

      // Simulate not found
      if (id === '999') {
        return c.json({ error: 'Post not found' }, 404)
      }

      return c.json({
        post: { id, title: 'Sample', body: 'Content' },
        comments: includeComments ? [] : undefined
      }, 200)
    }
  )

// Export type for client
export type AppType = typeof route
export default app

```

